const Ea = Math.max(10, P.Ea);
const drop = Math.min(P.drop, Ea - 5);
const dH = P.dH;
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: -120, yMax: 200 });
v.grid(); v.axes();
const Rlevel = 0;
const Plevel = dH;
function profile(x, barrier) {
  const base = Rlevel + (Plevel - Rlevel) * Math.min(1, Math.max(0, (x - 1) / 8));
  const bump = barrier * Math.exp(-Math.pow((x - 5) / 1.6, 2));
  return base + bump;
}
